 "content": "def transform(grid):
    """Expand 2-marked panel columns and 3-marked panel rows.

    The 8-valued grid lines divide the board into panels. Only full-sized
    panels participate; a smaller trailing edge panel is left unchanged.
    At crossings, the combined fill color is 6.
    """
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in g[r])]
    sep_cols = [c for c in range(w) if all(g[r][c] == 8 for r in range(h))]

    def spans(size, separators):
        out, start = [], 0
        for s in separators:
            if s > start:
                out.append((start, s))
            start = s + 1
        if start < size:
            out.append((start, size))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    if not rs or not cs:
        return g
    ph, pw = rs[0][1] - rs[0][0], cs[0][1] - cs[0][0]
    full_r = [i for i, (a, b) in enumerate(rs) if b - a == ph]
    full_c = [j for j, (a, b) in enumerate(cs) if b - a == pw]

    marked_rows, marked_cols = set(), set()
    for i in full_r:
        r0, r1 = rs[i]
        for j in full_c:
            c0, c1 = cs[j]
            colors = {g[r][c] for r in range(r0, r1) for c in range(c0, c1)}
            if 3 in colors:
                marked_rows.add(i)
            if 2 in colors:
                marked_cols.add(j)

    for i in full_r:
        r0, r1 = rs[i]
        for j in full_c:
            c0, c1 = cs[j]
            color = 6 if i in marked_rows and j in marked_cols else (
                3 if i in marked_rows else 2 if j in marked_cols else None
            )
            if color is not None:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        g[r][c] = color
    return g
